/usr/bin/bash -lc "python - <<'PY'
from pathlib import Path
for p in sorted(Path('sources').glob('*.md')):
 print('\\n',p)
 for n,line in enumerate(p.read_text().splitlines(),1):
  if any(v in line.lower() for v in ('check','verified','recheck','review','tested','correction','audit','result','computed','original')):
   print(f'{n}: [historical/assertion-bearing line withheld]')
  else: print(f'{n}: {line}')
PY"

